(* [comment removed for export] *)
Definition i_sec_range : Z := INST + 0x50.
Definition i_sec_bylog : Z := INST + 0xa8.
Definition i_gstat_alloc : Z := INST + 0x2c0.
Definition sec_range (m : mem) (PAB : Z) : Prop := rw_cells asegs m i_sec_range [C8 (Z_to_bv 64 PAB)].
Definition sec_junk (m : mem) : Prop :=
  (exists (b : byte) (j : list byte) (w1 w2 w3 w4 : word), rw_cells asegs m i_sec_sorted [C1 b; CB 7 j; C8 w1; C8 w2; C8 w3; C8 w4])
  /\ (exists bl : list word, length bl = 64%nat /\ u64arr asegs m i_sec_bylog bl)
  /\ (exists ga gm : word, rw_cells asegs m i_gstat_alloc [C8 ga; C8 gm]).

(* [comment removed for export] *)
Definition sec_name : Z := 0x21852.
Definition name_cells (m : mem) : Prop :=
  rw_cells asegs m 0x225d08 [C8 (Z_to_bv 64 0x227ed0)] /\ rw_cells asegs m 0x227ed0 [C8 (Z_to_bv 64 sec_name)].

(* [comment removed for export] *)
Definition sa_msz (SZ : Z) : Z := roundup4k SZ + 4096.

(* [comment removed for export] *)
Definition gobj (b n lo : Z) : Prop :=
  0 < b /\ b + n <= lo /\ (b + n <= 0x7fff7000 \/ 0x10007fff8000 <= b) /\ (b + n <= img_hull_lo \/ img_hull_hi <= b).
Definition sapart (b1 n1 b2 n2 : Z) : Prop := b1 + n1 <= b2 \/ b2 + n2 <= b1.
